python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
print('Sheets:', wb.sheetnames)
ws=wb['Task'] if 'Task' in wb.sheetnames else wb[wb.sheetnames[0]]
ds=wb['Data'] if 'Data' in wb.sheetnames else wb[wb.sheetnames[1]]
print('\n=== TASK SHEET INSPECTION ===')
for rng_name, rows in [('D12:D17', range(12,18)), ('D19:D24', range(19,25)), ('D26:D31', range(26,32))]:
    print(rng_name)
    for r in rows:
        c=ws[f'D{r}']
        print(f'  D{r}: value={c.value!r}, type={type(c.value).__name__}')
print('H10:L10 year headers')
for col in range(8,13):
    c=ws.cell(10,col)
    print(f'  {get_column_letter(col)}10: value={c.value!r}, type={type(c.value).__name__}')
print('H35:H40 labels')
for r in range(35,41):
    c=ws[f'H{r}']
    print(f'  H{r}: value={c.value!r}, type={type(c.value).__name__}')
print('D35:D40 labels')
for r in range(35,41):
    c=ws[f'D{r}']
    print(f'  D{r}: value={c.value!r}, type={type(c.value).__name__}')
print('Labels/non-empty cells in column D or G rows 35-50')
for r in range(35,51):
    dv=ws[f'D{r}'].value
    gv=ws[f'G{r}'].value
    if dv is not None or gv is not None:
        print(f'  row {r}: D={dv!r}, G={gv!r}')
print('Rows 10-11 around columns D-L')
for r in [10,11]:
    vals=[]
    for col in range(4,13):
        c=ws.cell(r,col)
        vals.append(f'{get_column_letter(col)}{r}={c.value!r}({type(c.value).__name__})')
    print('  ' + ' | '.join(vals))

print('\n=== DATA SHEET INSPECTION ===')
print('Dimensions:', ds.max_row, ds.max_column)
print('Rows 1-5 non-empty columns')
for r in range(1,6):
    vals=[]
    for col in range(1, ds.max_column+1):
        v=ds.cell(r,col).value
        if v is not None:
            vals.append(f'{get_column_letter(col)}{r}={v!r}({type(v).__name__})')
    print(f'  row {r}: ' + (' | '.join(vals) if vals else '<empty>'))
print('Rows 21-38 all non-empty columns')
for r in range(21,39):
    vals=[]
    for col in range(1, ds.max_column+1):
        v=ds.cell(r,col).value
        if v is not None:
            vals.append(f'{get_column_letter(col)}{r}={v!r}({type(v).__name__})')
    print(f'  row {r}: ' + (' | '.join(vals) if vals else '<empty>'))
print('\nCandidate header rows containing Task years:')
task_years=[ws.cell(10,c).value for c in range(8,13)]
year_strs={str(y) for y in task_years}
for r in range(1, ds.max_row+1):
    count=sum(1 for c in range(1,ds.max_column+1) if ds.cell(r,c).value in task_years or str(ds.cell(r,c).value) in year_strs)
    if count:
        print(f'  row {r}: count={count}; ' + ' | '.join(f'{get_column_letter(c)}={ds.cell(r,c).value!r}({type(ds.cell(r,c).value).__name__})' for c in range(1, ds.max_column+1) if ds.cell(r,c).value is not None))
print('Candidate columns matching Task series codes:')
task_codes=[ws[f'D{r}'].value for r in list(range(12,18))+list(range(19,25))+list(range(26,32))]
for col in range(1, ds.max_column+1):
    vals=[ds.cell(r,col).value for r in range(1, ds.max_row+1)]
    matches=[v for v in vals if v in task_codes]
    if matches:
        print(f'  column {get_column_letter(col)}: {len(matches)} matches; sample={matches[:10]!r}')
print('Exact data range dimensions inferred from non-empty cells:')
non=[]
for row in ds.iter_rows():
    for cell in row:
        if cell.value is not None:
            non.append((cell.row, cell.column))
if non:
    minr=min(r for r,c in non); maxr=max(r for r,c in non); minc=min(c for r,c in non); maxc=max(c for r,c in non)
    print(f'  non-empty bounding box: {get_column_letter(minc)}{minr}:{get_column_letter(maxc)}{maxr} ({maxr-minr+1} rows x {maxc-minc+1} cols)')

sample=ws['D12'].value
print('\nSample compare Task!D12 against matching Data values:')
print(f'  Task!D12={sample!r} type={type(sample).__name__}')
for row in ds.iter_rows():
    for cell in row:
        if cell.value == sample:
            print(f'  match at Data!{cell.coordinate}: {cell.value!r} type={type(cell.value).__name__}')
print('Year type compare:')
task_y=ws['H10'].value
print(f'  Task!H10={task_y!r} type={type(task_y).__name__}')
for r in range(1, ds.max_row+1):
    for c in range(1, ds.max_column+1):
        v=ds.cell(r,c).value
        if v == task_y or str(v)==str(task_y):
            print(f'  Data!{get_column_letter(c)}{r}={v!r} type={type(v).__name__} (equal={v==task_y})')
